-- Sample data for ALL exam statistics screens (teacher statistics page + student My Scores).
-- Run in the H2 console (http://localhost:8080/h2-console) AFTER the app has started once.
-- Uses existing users: teacher@example.com (id 3), student@example.com (id 2), student1..student5 (ids 4-8), student6 (id 9).
-- Exams are linked to course id 1 (Java Fundamentals) so they also show in My Scores > Course Scores / Grade Details; students 4-9 are enrolled in it.
-- Re-runnable: it deletes its own rows (ids >= 9000) first.

ALTER TABLE EXAM_ATTEMPT ADD COLUMN IF NOT EXISTS PASS_SCORE NUMERIC(8,2);

DELETE FROM SCORE_APPEAL WHERE ID >= 9000;
DELETE FROM EXAM_ATTEMPT_ANSWER WHERE ATTEMPT_ID >= 9000;
DELETE FROM EXAM_ATTEMPT_QUESTION WHERE ATTEMPT_ID >= 9000;
DELETE FROM EXAM_ATTEMPT WHERE ID >= 9000;
DELETE FROM EXAM_RESULT_PUBLICATION WHERE ID >= 9000;
DELETE FROM EXAM WHERE ID >= 9000;
DELETE FROM COURSE_ENROLLMENTS WHERE ID >= 9000;




























